insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_44_v1'
from (values
('127.251.d.11',3,'A worker deposits $1,000 at the end of each year into an account earning 5% per year. After 2 years, the account holds:','["$2,050", "$2,025", "$2,000", "$2,100"]'::jsonb,0,'First deposit grows to 1,050, plus the second deposit of 1,000: 2,050.','original'),
('127.251.d.11',4,'Which description fits an annuity?','["A single one-time payment", "A series of equal payments made at regular intervals", "A loan with no payments", "A random set of gifts"]'::jsonb,1,'An annuity is a stream of equal periodic payments.','original'),
('127.251.d.12',3,'A will mainly allows a person to:','["Choose a credit score", "Set a bank interest rate", "State who receives their property after death", "Avoid all taxes"]'::jsonb,2,'Wills direct asset distribution.','original'),
('127.251.d.12',4,'A trust differs from a will because a trust can:','["Never name a trustee", "Only take effect after a court ruling", "Only hold cash", "Hold and manage assets for beneficiaries, sometimes avoiding probate"]'::jsonb,3,'Trusts are managed by a trustee for beneficiaries.','original'),
('127.251.d.13',3,'A donation to a qualified charity can benefit the giver by:','["Possibly lowering taxable income when deductions are itemized", "Removing all taxes", "Always doubling income", "Guaranteeing a refund"]'::jsonb,0,'Charitable gifts may be deductible.','original'),
('127.251.d.13',4,'Which is a nonfinancial benefit of charitable giving?','["Avoiding budgeting", "Supporting causes the giver values and strengthening the community", "Raising credit card interest", "Increasing debt"]'::jsonb,1,'Giving has social value.','original'),
('127.251.d.1.A',3,'Using a spreadsheet to compare the monthly cost of two cell phone plans is applying mathematics to:','["An abstract proof only", "An unrelated puzzle", "A problem from everyday life", "A history lesson"]'::jsonb,2,'Math solves daily problems.','original'),
('127.251.d.1.A',4,'A family compares the total cost of buying and renting a home. This shows math applied to:','["An art project", "A pure number game", "A fictional story", "A real-world financial decision"]'::jsonb,3,'Financial choices use mathematics.','original'),
('127.251.d.1.B',3,'A good problem-solving model begins by:','["Analyzing the given information and what is being asked", "Ignoring the question", "Guessing an answer", "Skipping to the end"]'::jsonb,0,'Understand the problem first.','original'),
('127.251.d.1.B',4,'After solving a budget problem, a student should:','["Assume it is correct", "Evaluate whether the answer is reasonable", "Change the question", "Delete the work"]'::jsonb,1,'Check the solution''s reasonableness.','original'),
('127.251.d.1.C',3,'To compute compound interest over 30 years quickly and accurately, the best tool is:','["A coin flip", "A ruler", "A spreadsheet or financial calculator", "Counting on fingers"]'::jsonb,2,'Technology supports lengthy calculations.','original'),
('127.251.d.1.C',4,'Which tool is best for showing how a loan balance declines over time?','["A compass", "A stopwatch", "A thermometer", "A spreadsheet amortization table"]'::jsonb,3,'Spreadsheets organize repeated calculations.','original'),
('127.251.d.1.D',3,'Explaining to a classmate why a longer loan costs more interest is:','["Communicating mathematical ideas and reasoning", "Guessing", "Hiding the work", "Skipping steps"]'::jsonb,0,'Explanation shows understanding.','original'),
('127.251.d.1.D',4,'A student justifies a budget choice with numbers and clear words. This is:','["Using opinions only", "Communicating reasoning with mathematical language", "Avoiding evidence", "Using slang only"]'::jsonb,1,'Precise language communicates ideas.','original'),
('127.251.d.1.E',3,'A table showing month, interest, and balance for a loan is a:','["Hidden file", "Random list", "Representation that organizes information", "Unrelated chart"]'::jsonb,2,'Tables organize data.','original'),
('127.251.d.1.E',4,'Which representation best shows savings growth over time?','["A map", "A recipe card", "A phone number list", "A line graph"]'::jsonb,3,'Line graphs show change.','original'),
('127.251.d.1.F',3,'Noticing that doubling the interest rate roughly doubles simple interest is analyzing:','["A mathematical relationship", "A random fact", "A coincidence", "A rumor"]'::jsonb,0,'Relationships connect variables.','original'),
('127.251.d.1.F',4,'Connecting the formula for compound interest to a graph of growth is:','["Memorizing numbers", "Linking mathematical relationships to real situations", "Avoiding graphs", "Ignoring models"]'::jsonb,1,'Connections build understanding.','original'),
('127.251.d.1.G',3,'Using a graph and calculations to defend a retirement plan is:','["Avoiding proof", "Giving a guess", "Justifying mathematical arguments", "Skipping explanation"]'::jsonb,2,'Justifications use evidence.','original'),
('127.251.d.1.G',4,'A strong justification for choosing one loan over another includes:','["No numbers", "A friend''s opinion only", "A hunch", "Calculations and a clear explanation of the comparison"]'::jsonb,3,'Evidence supports claims.','original'),
('127.251.d.2.A',3,'Which is a source of income that is paid for work done?','["Wages and salaries", "Rent paid by you", "Loan payments made", "Gifts to others"]'::jsonb,0,'Earned income comes from work.','original'),
('127.251.d.2.A',4,'Money earned from a savings account is called:','["Wage income", "Interest income", "Sales tax", "Rental expense"]'::jsonb,1,'Savings earn interest.','original'),
('127.251.d.2.B',3,'Two jobs offer the same pay. One adds paid sick leave and health insurance. The better total offer is the one with:','["Fewer benefits", "The farther location", "More employee benefits", "The longer name"]'::jsonb,2,'Benefits add value.','original'),
('127.251.d.2.B',4,'Employer-paid health insurance is valuable because it:','["Lowers wages to zero", "Adds debt", "Raises taxes always", "Reduces what the employee must spend on medical costs"]'::jsonb,3,'Insurance offsets expenses.','original'),
('127.251.d.2.C',3,'Total pay before any deductions is called:','["Gross income", "Interest", "Taxable income only", "Net income"]'::jsonb,0,'Gross is before deductions.','original'),
('127.251.d.2.C',4,'Gross income of $50,000 minus a $12,000 deduction leaves taxable income of:','["$62,000", "$38,000", "$50,000", "$12,000"]'::jsonb,1,'50,000 - 12,000 = 38,000.','original'),
('127.251.d.2.D',3,'Federal income tax, Social Security, and Medicare withheld from a paycheck are:','["Gifts", "Refunds", "Payroll deductions", "Bonuses"]'::jsonb,2,'Deductions reduce take-home pay.','original'),
('127.251.d.2.D',4,'On a pay stub, FICA refers to deductions for:','["Savings bonds", "Rent", "Car insurance", "Social Security and Medicare"]'::jsonb,3,'FICA funds these programs.','original'),
('127.251.d.2.E',3,'Social Security taxes mainly fund:','["Retirement, disability, and survivor benefits", "School lunch only", "Space travel only", "Highway paint"]'::jsonb,0,'Social Security pays benefits.','original'),
('127.251.d.2.E',4,'Medicare payroll taxes help pay for:','["Free college", "Health care for people 65 and older and certain others", "Highway tolls", "Rent assistance"]'::jsonb,1,'Medicare covers health care for seniors.','original'),
('127.251.d.2.F',3,'A worker earns $800 in gross pay and has $160 withheld. Net pay is:','["$960", "$160", "$640", "$800"]'::jsonb,2,'800 - 160 = 640.','original'),
('127.251.d.2.F',4,'Gross pay is $1,500. Deductions total 22%. Net pay is:','["$1,830", "$1,100", "$330", "$1,170"]'::jsonb,3,'22% of 1,500 = 330; 1,500 - 330 = 1,170.','original'),
('127.251.d.2.G',3,'An independent contractor generally differs from an employee by:','["Paying their own self-employment taxes", "Being supervised full time", "Receiving employer insurance", "Having taxes withheld by an employer"]'::jsonb,0,'Contractors handle their own taxes.','original'),
('127.251.d.2.G',4,'A worker who sets their own hours and uses their own tools is likely:','["An employee", "An independent contractor", "An intern only", "A volunteer"]'::jsonb,1,'Control over work suggests contractor status.','original'),
('127.251.d.2.H',3,'A worker paid $12 per hour works 45 hours with time-and-a-half overtime after 40. Gross pay is:','["$630", "$600", "$570", "$540"]'::jsonb,2,'40 x 12 = 480; 5 x 18 = 90; total 570.','original'),
('127.251.d.2.H',4,'Federal minimum wage laws set:','["Profit limits", "The highest pay allowed", "Savings rates", "The lowest hourly pay most employers may offer"]'::jsonb,3,'Minimum wage is a floor.','original'),
('127.251.d.2.I',3,'Contributing $100 of pre-tax income to a retirement plan, versus after-tax income, usually:','["Lowers taxable income now", "Raises taxable income now", "Has no tax effect", "Doubles the tax"]'::jsonb,0,'Pre-tax contributions reduce current taxes.','original'),
('127.251.d.2.I',4,'A $200 pre-tax contribution for someone in a 25% bracket saves about:','["$200", "$50 in taxes", "$25", "$100"]'::jsonb,1,'25% of 200 = 50.','original'),
('127.251.d.2.J',3,'Total compensation includes wages and also:','["Only wages", "Only taxes", "Benefits such as insurance and retirement contributions", "Only tips"]'::jsonb,2,'Benefits add to pay.','original'),
('127.251.d.2.J',4,'An employer pays $40,000 in wages plus $8,000 in benefits. Total compensation is:','["$32,000", "$8,000", "$40,000", "$48,000"]'::jsonb,3,'40,000 + 8,000 = 48,000.','original'),
('127.251.d.2.K',3,'A self-employed worker typically must pay for their own:','["Health insurance and retirement savings", "Employer taxes", "Paid sick leave from an employer", "Employer match"]'::jsonb,0,'No employer provides benefits.','original'),
('127.251.d.2.K',4,'To match an employee''s $50,000 salary plus $10,000 in benefits, a contractor must earn about:','["$40,000", "$60,000 or more before extra costs", "$10,000", "$50,000"]'::jsonb,1,'They must cover benefits and extra taxes themselves.','original'),
('127.251.d.2.L',3,'During a recession, workers in many industries may face:','["Lower unemployment", "Guaranteed raises", "Fewer job openings and slower raises", "More openings always"]'::jsonb,2,'Conditions affect income.','original'),
('127.251.d.2.L',4,'A worker whose skills become obsolete due to automation is affected by:','["Fixed conditions only", "Interest rates only", "No outside factors", "Changing economic and technological conditions"]'::jsonb,3,'Technology shifts careers.','original'),
('127.251.d.3.A',3,'Taxable income is $40,000 and tax owed is $4,500. $5,200 was withheld. The result is:','["A $700 refund", "A $9,700 refund", "A $700 balance due", "No change"]'::jsonb,0,'Withheld exceeds owed by 700.','original'),
('127.251.d.3.A',4,'Which form do many employers give an employee to report annual wages and withholding?','["1040 itself", "W-2", "1099-DIV", "W-9"]'::jsonb,1,'The W-2 reports wages and withholding.','original'),
('127.251.d.3.B',3,'A stock bought for $2,000 is sold for $3,500. The capital gain is:','["$2,000", "$3,500", "$1,500", "$5,500"]'::jsonb,2,'3,500 - 2,000 = 1,500.','original'),
('127.251.d.3.B',4,'If the long-term capital gains rate is 15%, tax on a $1,500 gain is:','["$1,350", "$150", "$22.50", "$225"]'::jsonb,3,'0.15 x 1,500 = 225.','original'),
('127.251.d.3.C',3,'Self-employed people pay Social Security and Medicare taxes covering:','["Both the employee and employer shares", "Neither share", "Only the employer share", "Only state taxes"]'::jsonb,0,'They pay both halves.','original'),
('127.251.d.3.C',4,'Assume a 15.3% self-employment tax rate on $10,000 of net earnings. The tax is:','["$15,300", "$1,530", "$1,000", "$153"]'::jsonb,1,'0.153 x 10,000 = 1,530.','original'),
('127.251.d.3.D',3,'The best place to find current federal estate tax rates is the:','["A game forum", "A comic book", "IRS website", "A random blog"]'::jsonb,2,'Official sources list current rates.','original'),
('127.251.d.3.D',4,'An inheritance tax is paid by:','["The bank", "The executor only", "The deceased", "The person who receives the property in states that have one"]'::jsonb,3,'Heirs may owe inheritance tax.','original'),
('127.251.d.3.E',3,'A gift given to someone may trigger a federal gift tax only when it:','["Exceeds the annual exclusion amount", "Is a card", "Is under the limit", "Is any size"]'::jsonb,0,'Small gifts are excluded.','original'),
('127.251.d.3.E',4,'An estate worth less than the federal exemption generally owes:','["Double tax", "No federal estate tax", "Gift tax only", "Maximum estate tax"]'::jsonb,1,'Exemptions shield smaller estates.','original'),
('127.251.d.3.F',3,'A saver earns $200 in interest and is in the 22% bracket. Tax on that interest is:','["$200", "$4.40", "$44", "$22"]'::jsonb,2,'0.22 x 200 = 44.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_44_v1'
from (values
('127.251.d.3.F',4,'Plotting tax owed against income and fitting a trend line is an example of:','["Ignoring brackets", "Skipping data", "Guessing", "Using regression to analyze tax data"]'::jsonb,3,'Regression models data.','original'),
('127.251.d.3.G',3,'A personal exemption is an amount that, when allowed, is subtracted from:','["Income before computing tax", "Net pay only", "Interest earned", "Tax after the bill"]'::jsonb,0,'Exemptions reduce taxable income.','original'),
('127.251.d.3.G',4,'If each exemption is $4,000 and a family claims 3, the exemptions total:','["$4,000", "$12,000", "$1,333", "$7,000"]'::jsonb,1,'3 x 4,000 = 12,000.','original'),
('127.251.d.3.H',3,'A taxpayer''s individually listed deductions total $14,500, and the standard deduction is $14,000. To save the most tax, the taxpayer should generally:','["File no return", "Skip both", "Itemize", "Take the standard deduction"]'::jsonb,2,'Choose the larger deduction.','original'),
('127.251.d.3.H',4,'Which is commonly itemized?','["Clothing", "Vacation costs", "Groceries", "Mortgage interest"]'::jsonb,3,'Mortgage interest is a typical itemized deduction.','original'),
('127.251.d.3.I',3,'A taxpayer who itemizes and gives $500 to a qualified charity in the 22% bracket reduces tax by:','["$110", "$22", "$500", "$1,100"]'::jsonb,0,'0.22 x 500 = 110.','original'),
('127.251.d.3.I',4,'To deduct a charitable gift, the receiving group generally must be:','["A friend", "A qualified tax-exempt organization", "A foreign company only", "Any individual"]'::jsonb,1,'Only qualified charities count.','original'),
('127.251.d.3.J',3,'A taxpayer''s filing status affects the:','["Credit limit", "Car insurance", "Tax brackets and standard deduction used", "Bank interest rate"]'::jsonb,2,'Status determines the schedule.','original'),
('127.251.d.3.J',4,'Which is a federal filing status?','["Landlord", "Partner", "Renter", "Head of household"]'::jsonb,3,'Head of household is a status.','original'),
('127.251.d.3.K',3,'Suppose a 10% rate applies to the first $10,000 and 20% above that. Tax on $20,000 is:','["$3,000", "$2,500", "$2,000", "$4,000"]'::jsonb,0,'1,000 + 2,000 = 3,000.','original'),
('127.251.d.3.K',4,'In that same example, the effective tax rate on $20,000 is:','["10%", "15%", "30%", "20%"]'::jsonb,1,'3,000 / 20,000 = 0.15.','original'),
('127.251.d.3.L',3,'An education tax credit reduces:','["Only taxable income", "Gross pay", "The amount of tax owed dollar for dollar", "Only the refund"]'::jsonb,2,'Credits reduce tax directly.','original'),
('127.251.d.3.L',4,'Whether a student can be claimed as a dependent can affect a taxpayer''s:','["Credit score", "Bank fees", "Car loan rate", "Tax liability and credits"]'::jsonb,3,'Dependency changes tax outcomes.','original'),
('127.251.d.3.M',3,'One option for preparing a tax return is:','["Using tax software", "Asking a stranger", "Skipping it", "Guessing the amount"]'::jsonb,0,'Software guides filers.','original'),
('127.251.d.3.M',4,'Free tax help for some filers is offered through the:','["A rumor mill", "IRS Volunteer Income Tax Assistance program", "A coupon book", "A game site"]'::jsonb,1,'VITA provides free help.','original'),
('127.251.d.4.A',3,'Paying with money pulled directly from a checking account at purchase uses a:','["Gift card only", "Store charge", "Debit card", "Credit card"]'::jsonb,2,'Debit cards draw from your account.','original'),
('127.251.d.4.A',4,'Moving money between accounts online is called an:','["Money order only", "Cash deposit", "Paper check", "Electronic funds transfer"]'::jsonb,3,'EFTs move money digitally.','original'),
('127.251.d.4.B',3,'A savings account that pays interest is an advantage because it:','["Grows the balance over time", "Removes the balance", "Hides money", "Charges you"]'::jsonb,0,'Interest earns money.','original'),
('127.251.d.4.B',4,'A disadvantage of some interest-bearing accounts is:','["Guaranteed loss", "Withdrawal limits or minimum balance rules", "No safety", "Zero access ever"]'::jsonb,1,'Rules may limit use.','original'),
('127.251.d.4.C',3,'$1,000 earns simple interest at 5% for 3 years. The interest is:','["$157.63", "$1,150", "$150", "$50"]'::jsonb,2,'1,000 x 0.05 x 3 = 150.','original'),
('127.251.d.4.C',4,'$1,000 compounds annually at 5% for 2 years. The balance is:','["$1,125", "$1,050", "$1,100", "$1,102.50"]'::jsonb,3,'1,000 x 1.05^2 = 1,102.50.','original'),
('127.251.d.4.D',3,'Savings growing by a fixed percent each period follow:','["An exponential function", "A linear function", "A random function", "A constant function"]'::jsonb,0,'Compounding is exponential.','original'),
('127.251.d.4.D',4,'On a graph, compound growth looks like a curve that:','["Is a straight line", "Rises faster over time", "Falls to zero", "Stays flat"]'::jsonb,1,'Exponential growth accelerates.','original'),
('127.251.d.4.E',3,'When checking a bank statement, you should compare it to:','["Last year''s weather", "A rumor", "Your own records of deposits and withdrawals", "Your friend''s records"]'::jsonb,2,'Reconciliation finds errors.','original'),
('127.251.d.4.E',4,'An unfamiliar charge on a statement should be:','["Paid twice", "Hidden", "Ignored", "Reported to the bank promptly"]'::jsonb,3,'Report errors quickly.','original'),
('127.251.d.4.F',3,'Comparing a bank and a credit union on fees and rates is:','["Comparing community financial services", "Ignoring options", "Skipping research", "Guessing"]'::jsonb,0,'Shop for services.','original'),
('127.251.d.4.F',4,'Credit unions are different from banks because they are typically:','["Stock exchanges", "Member-owned nonprofit cooperatives", "Insurance firms", "Government agencies"]'::jsonb,1,'Members own credit unions.','original'),
('127.251.d.4.G',3,'Money to buy a car can come from savings, earnings, or:','["Free gifts only", "Coupons", "Debt such as a loan", "Nothing"]'::jsonb,2,'Debt is a funding source.','original'),
('127.251.d.4.G',4,'Paying with savings instead of a loan avoids:','["Insurance", "All taxes", "Depreciation", "Interest costs"]'::jsonb,3,'No loan means no interest.','original'),
('127.251.d.5.A',3,'A credit card that returns a percentage of purchases offers:','["Cash back rewards", "A lower limit", "Free groceries always", "A higher balance"]'::jsonb,0,'Cash back is a reward.','original'),
