('127.251.d.5.B',3,'A $1,000 credit card balance at 18% APR has a monthly rate of 1.5%. First-month interest is:','["$150", "$18", "$15", "$1.50"]'::jsonb,2,'1,000 x 0.015 = 15.','original'),
('127.251.d.5.B',4,'Paying only the minimum on a high-rate card usually:','["Reduces total cost", "Eliminates interest", "Lowers the rate", "Increases total interest paid"]'::jsonb,3,'Minimum payments prolong debt.','original'),
('127.251.d.5.C',3,'A graph comparing balances of two loans over time shows that the loan with the higher rate:','["Decreases more slowly", "Vanishes at once", "Stays equal", "Falls faster"]'::jsonb,0,'Higher rate means more interest.','original'),
