('127.253.d.3.D',3,'The present value of $1,000 received in 2 years with a 5% discount rate is about:','["$950", "$1,100", "$1,000", "$907"]'::jsonb,3,'1,000 / 1.1025 = 907.03.','original'),
('127.253.d.3.D',4,'The future value of $500 after 2 years at 4% compounded annually is:','["$540.80", "$580", "$520", "$540"]'::jsonb,0,'500 x 1.0816 = 540.80.','original'),
